items = [p['Product Name'] for p in fashion_products]
revenue = {p['Product Name']: p['Revenue'] for p in fashion_products}
demand = {p['Product Name']: int(round(p['Demand'])) for p in fashion_products}
inventory = {p['Product Name']: int(round(p['Initial Inventory'])) for p in fashion_products}
for i in items:
    if i not in revenue or i not in demand or i not in inventory:
        raise ValueError(f'Missing data for product {i}')
m = gp.Model('Fashion_Revenue_Max')
x = m.addVars(items, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((revenue[i] * x[i] for i in items)), GRB.MAXIMIZE)
m.addConstrs((x[i] <= inventory[i] for i in items), name='')
m.addConstrs((x[i] <= demand[i] for i in items), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')